	first := manager.CXFunctionAlloc()
	manager.CXFunctionGet(first).LineCount = 11
	second := manager.CXFunctionAlloc()
	manager.CXFunctionGet(second).LineCount = 22
	CXFunctionMngTestCheck(t, &manager, "two allocs", 2, 2)
	if objmodel.GidTypeTag(int64(first)) != CXFunctionGidTypeTag || objmodel.GidGeneration(int64(first)) != objmodel.GidGenerationFirst {
		t.Fatalf("first Gid %#x has the wrong tag or generation", int64(first))
	}
	if manager.CXFunctionGet(first).LineCount != 11 || manager.CXFunctionGet(second).LineCount != 22 {
		t.Fatal("Get does not return the allocated objects")
	}

	manager.CXFunctionRelease(first)
	CXFunctionMngTestCheck(t, &manager, "release", 1, 2)
	third := manager.CXFunctionAlloc()
	CXFunctionMngTestCheck(t, &manager, "reuse", 2, 2)
	if objmodel.GidIndex(int64(third)) != objmodel.GidIndex(int64(first)) {
		t.Fatal("Alloc did not reuse the released slot")
	}
	if objmodel.GidGeneration(int64(third)) != objmodel.GidGeneration(int64(first))+1 {
		t.Fatalf("generation %d after one release, want %d", objmodel.GidGeneration(int64(third)), objmodel.GidGeneration(int64(first))+1)
	}
